1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"slices"
10	)
11	
12	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
13	// truncated JSON, trailing data after the object, an unknown version,
14	// missing, mistyped, unknown, or duplicated fields, a null where version,
15	// tip, height, hash, parent, or a transaction identifier is required,
16	// heights that do not ascend consecutively from 1, an empty or duplicated
17	// hash, a broken parent link, a version-2 timestamp that is missing or
18	// neither null nor a non-negative integer, or a tip that disagrees with the
19	// block list. A rejected restore never changes the index.
20	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
21	
22	const (
23		// snapshotVersion1 is the timestamp-less layout. It stays readable
24		// indefinitely; its blocks restore with missing timestamps.
25		snapshotVersion1 = 1
26		// snapshotVersion2 adds a required timestamp field to every block:
27		// either a non-negative Unix-seconds integer or null for missing time.
28		snapshotVersion2 = 2
29	)
30	
31	// snapshotDoc is the version-1 wire form of an exported main chain.
32	type snapshotDoc struct {
33		Version int64           `json:"version"`
34		Tip     int64           `json:"tip"`
35		Blocks  []snapshotBlock `json:"blocks"`
36	}
37	
38	// snapshotBlock is the version-1 wire form of one block.
39	type snapshotBlock struct {
40		Height int64    `json:"height"`
41		Hash   string   `json:"hash"`
42		Parent string   `json:"parent"`
43		Txs    []string `json:"txs"`
44	}
45	
46	// snapshotDocV2 is the timestamp-bearing wire form.
47	type snapshotDocV2 struct {
48		Version int64             `json:"version"`
49		Tip     int64             `json:"tip"`
50		Blocks  []snapshotBlockV2 `json:"blocks"`
51	}
52	
53	// snapshotBlockV2 is the version-2 wire form of one block. A nil Timestamp
54	// serializes as null.
55	type snapshotBlockV2 struct {
56		Height    int64    `json:"height"`
57		Hash      string   `json:"hash"`
58		Parent    string   `json:"parent"`
59		Txs       []string `json:"txs"`
60		Timestamp *int64   `json:"timestamp"`
61	}
62	
63	// Export writes the current main chain to w as a JSON snapshot: a single
64	// object with version, tip, and the blocks ordered by ascending height, each
65	// carrying its transactions in order. The same main chain always produces
66	// the same bytes, regardless of the reorg, restore, or query history that
67	// led to it. Only blocks in effect at export time appear; nothing the index
68	// once held and later dropped is included.
69	//
70	// A chain whose blocks all lack timestamps keeps the original version-1
71	// layout, byte for byte. As soon as any block carries a timestamp the
72	// document is version 2 and every block includes a timestamp field: a
73	// non-negative integer or null for a missing timestamp.
74	//
75	// Export observes one complete chain state and never modifies the index.
76	// The chain is copied under the lock and serialized afterwards, so queries
77	// and appends proceed while the stream is still being written. A write
78	// failure is reported and leaves the index untouched.
79	func (index *Index) Export(w io.Writer) error {
80		index.mu.Lock()
81		version := int64(snapshotVersion1)
82		for height := int64(1); height <= index.Tip; height++ {
83			if index.Blocks[height].Time != nil {
84				version = snapshotVersion2
85				break
86			}
87		}
88		var raw []byte
89		var err error
90		if version == snapshotVersion1 {
91			doc := snapshotDoc{
92				Version: snapshotVersion1,
93				Tip:     index.Tip,
94				Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
95			}
96			for height := int64(1); height <= index.Tip; height++ {
97				block := index.Blocks[height]
98				txs := make([]string, len(block.Txs))
99				copy(txs, block.Txs)
100				doc.Blocks = append(doc.Blocks, snapshotBlock{
101					Height: block.Height,
102					Hash:   block.Hash,
103					Parent: block.Parent,
104					Txs:    txs,
105				})
106			}
107			index.mu.Unlock()
108			raw, err = json.Marshal(doc)
109		} else {
110			doc := snapshotDocV2{
111				Version: snapshotVersion2,
112				Tip:     index.Tip,
113				Blocks:  make([]snapshotBlockV2, 0, int(index.Tip)),
114			}
115			for height := int64(1); height <= index.Tip; height++ {
116				block := index.Blocks[height]
117				txs := make([]string, len(block.Txs))
118				copy(txs, block.Txs)
119				entry := snapshotBlockV2{
120					Height: block.Height,
121					Hash:   block.Hash,
122					Parent: block.Parent,
123					Txs:    txs,
124				}
125				if block.Time != nil {
126					t := *block.Time
127					entry.Timestamp = &t
128				}
129				doc.Blocks = append(doc.Blocks, entry)
130			}
131			index.mu.Unlock()
132			raw, err = json.Marshal(doc)
133		}
134		if err != nil {
135			panic(err) // snapshot docs only contain marshalable fields
136		}
137		n, err := w.Write(raw)
138		if err != nil {
139			return fmt.Errorf("indexroom: export snapshot: %w", err)
140		}
141		if n != len(raw) {
142			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
143		}
144		return nil
145	}
146	
147	// Restore replaces the whole main chain with the snapshot read from r. The
148	// input must be exactly one snapshot object, optionally followed by
149	// whitespace; every block is validated — including heights ascending from 1,
150	// non-empty unique hashes, and parent linkage — before anything is applied.
151	// The first block's parent is exempt from linkage: it names the chain start
152	// and need not be indexed.
153	//
154	// The replacement takes effect as one complete operation: on success the
155	// index holds exactly the snapshot chain with no leftover heights or hashes,
156	// and on any failure — a read error or an invalid block discovered at the
157	// very end — the current chain and every previously issued cursor remain as
158	// they were. The stream is consumed and validated before the lock is taken,
159	// so the index stays queryable and appendable while the restore is reading.
160	//
161	// After a successful restore, cursors issued earlier by this same index keep
162	// working wherever the pinned range still matches and the tip still covers
163	// it; otherwise continuations fail with ErrQueryChanged as usual.
164	func (index *Index) Restore(r io.Reader) error {
165		tip, blocks, err := parseSnapshot(r)
166		if err != nil {
167			return err
168		}
169		stored := make(map[int64]Block, len(blocks))
170		byHash := make(map[string]int64, len(blocks))
171		for _, block := range blocks {
172			stored[block.Height] = block
173			byHash[block.Hash] = block.Height
174		}
175		index.mu.Lock()
176		index.Blocks = stored
177		index.ByHash = byHash
178		index.Tip = tip
179		index.mu.Unlock()
180		return nil
181	}
182	
183	// parseSnapshot reads and fully validates one snapshot document. It returns
184	// the tip height and the validated blocks in ascending height order.
185	func parseSnapshot(r io.Reader) (int64, []Block, error) {
186		dec := json.NewDecoder(r)
187		tok, err := dec.Token()
188		if err != nil {
189			return 0, nil, classifySnapshotErr(err)
190		}
191		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
192			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
193		}
194	
195		// Top-level fields are captured raw so blocks can be parsed with the
196		// strict schema matching the declared version, whatever the field order,
197		// and so null can be told apart from a zero value.
198		var (
199			rawVersion, rawTip   json.RawMessage
200			rawBlocks            json.RawMessage
201			haveVersion, haveTip bool
202			haveBlocks           bool
203			seen                 = map[string]bool{}
204		)
205		for dec.More() {
206			key, err := snapshotKey(dec)
207			if err != nil {
208				return 0, nil, err
209			}
210			if seen[key] {
211				return 0, nil, invalidSnapshot("duplicate field %q", key)
212			}
213			seen[key] = true
214			switch key {
215			case "version":
216				if err := dec.Decode(&rawVersion); err != nil {
217					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
218				}
219				haveVersion = true
220			case "tip":
221				if err := dec.Decode(&rawTip); err != nil {
222					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
223				}
224				haveTip = true
225			case "blocks":
226				if err := dec.Decode(&rawBlocks); err != nil {
227					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
228				}
229				haveBlocks = true
230			default:
231				return 0, nil, invalidSnapshot("unknown field %q", key)
232			}
233		}
234		if _, err := dec.Token(); err != nil { // closing '}'
235			return 0, nil, classifySnapshotErr(err)
236		}
237		// Only whitespace may follow the snapshot object.
238		if _, err := dec.Token(); err != io.EOF {
239			if err == nil {
240				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
241			}
242			return 0, nil, classifySnapshotErr(err)
243		}
244	
245		if !haveVersion {
246			return 0, nil, invalidSnapshot("missing field %q", "version")
247		}
248		if !haveTip {
249			return 0, nil, invalidSnapshot("missing field %q", "tip")
250		}
251		if !haveBlocks {
252			return 0, nil, invalidSnapshot("missing field %q", "blocks")
253		}
254		version, err := snapshotInt64(rawVersion, "version")
255		if err != nil {
256			return 0, nil, err
257		}
258		tip, err := snapshotInt64(rawTip, "tip")
259		if err != nil {
260			return 0, nil, err
261		}
262		if version != snapshotVersion1 && version != snapshotVersion2 {
263			return 0, nil, invalidSnapshot("unsupported version %d", version)
264		}
265	
266		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
267		blocks, err := parseSnapshotBlocks(blockDec, version)
268		if err != nil {
269			return 0, nil, err
270		}
271		if _, err := blockDec.Token(); err != io.EOF {
272			if err == nil {
273				return 0, nil, invalidSnapshot("trailing data after the blocks array")
274			}
275			return 0, nil, classifySnapshotErr(err)
276		}
277	
278		lastHeight := int64(0)
279		if len(blocks) > 0 {
280			lastHeight = blocks[len(blocks)-1].Height
281		}
282		if tip != lastHeight {
283			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
284		}
285		return tip, blocks, nil
286	}
287	
288	// parseSnapshotBlocks reads the blocks array value, validating heights,
289	// hashes, parent links, and (for version 2) timestamps as it goes.
290	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
291		tok, err := dec.Token()
292		if err != nil {
293			return nil, classifySnapshotErr(err)
294		}
295		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
296			return nil, invalidSnapshot("field %q must be an array", "blocks")
297		}
298		blocks := []Block{}
299		seenHash := map[string]bool{}
300		for dec.More() {
301			var block Block
302			if version == snapshotVersion2 {
303				block, err = parseSnapshotBlockV2(dec)
304			} else {
305				block, err = parseSnapshotBlock(dec)
306			}
307			if err != nil {
308				return nil, err
309			}
310			want := int64(len(blocks) + 1)
311			if block.Height != want {
312				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
313			}
314			if block.Hash == "" {
315				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
316			}
317			if seenHash[block.Hash] {
318				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
319			}
320			seenHash[block.Hash] = true
321			// The first block's parent names the chain start and is exempt from
322			// linkage; every later block must point at its predecessor.
323			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
324				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
325			}
326			blocks = append(blocks, block)
327		}
328		if _, err := dec.Token(); err != nil { // closing ']'
329			return nil, classifySnapshotErr(err)
330		}
331		return blocks, nil
332	}
333	
334	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
335	// fields height, hash, parent, and txs.
336	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
337		var block Block
338		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs")
339		if err != nil {
340			return block, err
341		}
342		return finishSnapshotBlock(fields)
343	}
344	
345	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
346	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
347	// null or a non-negative integer; the block returns a nil time for null.
348	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
349		var block Block
350		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs", "timestamp")
351		if err != nil {
352			return block, err
353		}
354		if _, ok := fields["timestamp"]; !ok {
355			return block, invalidSnapshot("block is missing field %q", "timestamp")
356		}
357		block, err = finishSnapshotBlock(fields)
358		if err != nil {
359			return block, err
360		}
361		t, err := parseSnapshotTimestamp(fields["timestamp"])
362		if err != nil {
363			return Block{}, err
364		}
365		block.Time = t
366		return block, nil
367	}
368	
369	// readSnapshotBlockObject reads one block object and captures each known
370	// field's raw value. Fields are decoded only after the whole object is read,
371	// so a null can be rejected per field and a txs element error can name the
372	// block's height whatever order the fields arrive in.
373	func readSnapshotBlockObject(dec *json.Decoder, known ...string) (map[string]json.RawMessage, error) {
374		tok, err := dec.Token()
375		if err != nil {
376			return nil, classifySnapshotErr(err)
377		}
378		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
379			return nil, invalidSnapshot("block must be a JSON object")
380		}
381		fields := map[string]json.RawMessage{}
382		for dec.More() {
383			key, err := snapshotKey(dec)
384			if err != nil {
385				return nil, err
386			}
387			if _, dup := fields[key]; dup {
388				return nil, invalidSnapshot("duplicate block field %q", key)
389			}
390			if !slices.Contains(known, key) {
391				return nil, invalidSnapshot("unknown block field %q", key)
392			}
393			var raw json.RawMessage
394			if err := dec.Decode(&raw); err != nil {
395				return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
396			}
397			fields[key] = raw
398		}
399		if _, err := dec.Token(); err != nil { // closing '}'
400			return nil, classifySnapshotErr(err)
401		}
402		return fields, nil
403	}
404	
405	// finishSnapshotBlock decodes the shared block fields from their raw values,
406	// requiring height, hash, parent, and txs and rejecting null for each.
407	func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
408		var block Block
409		for _, field := range []string{"height", "hash", "parent", "txs"} {
410			if _, ok := fields[field]; !ok {
411				return block, invalidSnapshot("block is missing field %q", field)
412			}
413		}
414		var err error
415		if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
416			return block, err
417		}
418		if block.Hash, err = snapshotString(fields["hash"], "hash"); err != nil {
419			return block, err
420		}
421		if block.Parent, err = snapshotString(fields["parent"], "parent"); err != nil {
422			return block, err
423		}
424		txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
425		if err != nil {
426			return block, err
427		}
428		block.Txs = txs
429		return block, nil
430	}
431	
432	// snapshotInt64 decodes one required integer field, rejecting null rather
433	// than letting it pass as zero.
434	func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
435		if isSnapshotNull(raw) {
436			return 0, invalidSnapshot("field %q must not be null", field)
437		}
438		var v int64
439		if err := json.Unmarshal(raw, &v); err != nil {
440			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
441		}
442		return v, nil
443	}
444	
445	// snapshotString decodes one required string field, rejecting null rather
446	// than letting it pass as the empty string.
447	func snapshotString(raw json.RawMessage, field string) (string, error) {
448		if isSnapshotNull(raw) {
449			return "", invalidSnapshot("field %q must not be null", field)
450		}
451		var s string
452		if err := json.Unmarshal(raw, &s); err != nil {
453			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
454		}
455		return s, nil
456	}
457	
458	// isSnapshotNull reports whether a raw field value is the JSON null literal.
459	func isSnapshotNull(raw json.RawMessage) bool {
460		return string(raw) == "null"
461	}
462	
463	// parseSnapshotTimestamp reads one timestamp value: null for a missing
464	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
465	// distinct from null.
466	func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
467		var t *int64
468		if err := json.Unmarshal(raw, &t); err != nil {
469			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
470		}
471		if t != nil && *t < 0 {
472			return nil, invalidSnapshot("timestamp must not be negative")
473		}
474		return t, nil
475	}
476	
477	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
478	// identifiers exactly as written. A null element is rejected, naming the
479	// block's height and the element's zero-based position.
480	func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
481		tok, err := dec.Token()
482		if err != nil {
483			return nil, classifySnapshotErr(err)
484		}
485		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
486			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
487		}
488		txs := []string{}
489		for dec.More() {
490			var tx *string
491			if err := dec.Decode(&tx); err != nil {
492				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
493			}
494			if tx == nil {
495				return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
496			}
497			txs = append(txs, *tx)
498		}
499		if _, err := dec.Token(); err != nil { // closing ']'
500			return nil, classifySnapshotErr(err)
501		}
502		return txs, nil
503	}
504	
505	// snapshotKey reads the next object key.
506	func snapshotKey(dec *json.Decoder) (string, error) {
507		tok, err := dec.Token()
508		if err != nil {
509			return "", classifySnapshotErr(err)
510		}
511		key, ok := tok.(string)
512		if !ok {
513			return "", invalidSnapshot("object key must be a string")
514		}
515		return key, nil
516	}
517	
518	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
519	func invalidSnapshot(format string, args ...any) error {
520		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
521	}
522	
523	// classifySnapshotErr maps decoder failures onto the snapshot error model:
524	// malformed JSON, wrong value types, and truncation are snapshot errors,
525	// while anything else is an underlying read failure reported as-is.
526	func classifySnapshotErr(err error) error {
527		var syntaxErr *json.SyntaxError
528		var typeErr *json.UnmarshalTypeError
529		switch {
530		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
531			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
532		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
533			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
534		default:
535			return fmt.Errorf("indexroom: read snapshot: %w", err)
536		}
537	}
538

