			if inner[i+1] != 'u' {
				i += 2
				continue
			}
			if i+6 > len(inner) {
				return true
			}
			r1, ok := snapshotHex(inner[i+2 : i+6])
			if !ok {
				return true
			}
			switch {
			case r1 >= 0xD800 && r1 <= 0xDBFF:
				// High surrogate: must be immediately followed by a low
				// surrogate escape.
				if i+12 <= len(inner) && inner[i+6] == '\\' && inner[i+7] == 'u' {
					if r2, ok := snapshotHex(inner[i+8 : i+12]); ok && r2 >= 0xDC00 && r2 <= 0xDFFF {
						i += 12
						continue
					}
				}
				return false
			case r1 >= 0xDC00 && r1 <= 0xDFFF:
				return false
			}
			i += 6
		case c < utf8.RuneSelf:
			i++
		default:
			r, size := utf8.DecodeRune(inner[i:])
			if r == utf8.RuneError && size == 1 {
				return false
			}
			i += size
		}
	}
	return true
}
```

Note: utf8.DecodeRune on invalid returns size 1; a real U+FFFD encoded returns size 3. Good.

