package indexroom

import (
	"errors"
	"fmt"
	"strings"
	"testing"
)

func TestScratchStringEncoding(t *testing.T) {
	mk := func(hash, parent string, txs []string) string {
		txJSON := "["
		for i, tx := range txs {
			if i > 0 {
				txJSON += ","
			}
			txJSON += `"` + tx + `"`
		}
		txJSON += "]"
		return `{"version":1,"tip":1,"blocks":[{"height":1,"hash":"` + hash +
			`","parent":"` + parent + `","txs":` + txJSON + `}]}`
	}

	// Invalid UTF-8 byte in hash.
	bad := mk("h\xff1", "g", nil)
	err := New().Restore(strings.NewReader(bad))
	fmt.Println("invalid utf8 hash:", err)
	if !errors.Is(err, ErrInvalidSnapshot) {
		t.Fatal("want ErrInvalidSnapshot")
	}

	// Lone high surrogate in parent.
	err = New().Restore(strings.NewReader(mk("h1", `g𝜜`, nil)))
	fmt.Println("lone high:", err)
	if !errors.Is(err, ErrInvalidSnapshot) {
		t.Fatal("want ErrInvalidSnapshot")
	}

	// Reversed pair in tx.
	err = New().Restore(strings.NewReader(mk("h1", "g", []string{`\uDE00\uD83D`})))
	fmt.Println("reversed pair:", err)
	if !errors.Is(err, ErrInvalidSnapshot) {
		t.Fatal("want ErrInvalidSnapshot")
	}

	// Valid pair (emoji) accepted.
	idx := New()
	if err := idx.Restore(strings.NewReader(mk("h\U0001F600", "g", []string{"\U0001F600"}))); err != nil {
		t.Fatalf("valid pair rejected: %v", err)
	}
	if idx.Blocks[1].Hash != "h\U0001F600" {
		t.Fatalf("hash=%q", idx.Blocks[1].Hash)
	}

	// Chinese direct vs escaped produce the same identifier.
	a, b := New(), New()
	if err := a.Restore(strings.NewReader(mk("中文", "g", nil))); err != nil {
		t.Fatal(err)
	}
	if err := b.Restore(strings.NewReader(mk(`中文`, "g", nil))); err != nil {
		t.Fatal(err)
	}
	if a.Blocks[1].Hash != b.Blocks[1].Hash {
		t.Fatalf("direct vs escaped differ: %q vs %q", a.Blocks[1].Hash, b.Blocks[1].Hash)
	}

	// Literal U+FFFD accepted.
	if err := New().Restore(strings.NewReader(mk("h�", "g", nil))); err != nil {
		t.Fatalf("literal U+FFFD rejected: %v", err)
	}

	// Literal backslash-u text preserved verbatim.
	idx = New()
	if err := idx.Restore(strings.NewReader(mk(`h\\u0041`, "g", nil))); err != nil {
		t.Fatal(err)
	}
	if idx.Blocks[1].Hash != `h\\u0041`[:1]+`\`+`u0041` && idx.Blocks[1].Hash != `h\`+`u0041` {
		t.Fatalf("hash=%q", idx.Blocks[1].Hash)
	}
	fmt.Println("backslash text hash:", idx.Blocks[1].Hash)

	// Error names field, height, position; last-block failure leaves chain intact.
	src := txChain(t, []string{"a"}, []string{"b"})
	blocks, byHash, tip := snapshot(src)
