				t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
			}
			for _, want := range tc.want {
				if !strings.Contains(err.Error(), want) {
					t.Fatalf("err=%v, want it to mention %q", err, want)
				}
			}
